package reconciliationnetting

type Item struct {
	ID       string
	Currency string
	Amount   int64
}

type Group struct {
	Internal []Item
	External []Item
}

func Reconcile(internal, external []Item) []Group {
	var groups []Group
	used := make([]bool, len(internal))

	for _, bankItem := range external {
		components, ok := matchingComponents(internal, used, bankItem.Currency, bankItem.Amount)
		if !ok {
			continue
		}

		matched := make([]Item, len(components))
		for index, component := range components {
			used[component] = true
			matched[index] = internal[component]
		}
		groups = append(groups, Group{Internal: matched, External: []Item{bankItem}})
	}
	return groups
}

func matchingComponents(items []Item, used []bool, currency string, amount int64) ([]int, bool) {
	var search func(int, int64) bool
	components := make([]int, 0)

	search = func(index int, total int64) bool {
		if index == len(items) {
			return len(components) > 0 && total == amount
		}

		if !used[index] && items[index].Currency == currency {
			components = append(components, index)
			if search(index+1, total+items[index].Amount) {
				return true
			}
			components = components[:len(components)-1]
		}

		return search(index+1, total)
	}

	if !search(0, 0) {
		return nil, false
	}
	return components, true
}

